// Relay Moth Forest — Pretty Graphics Edition 4.14
// WebGL2 HD-remake renderer. Gameplay coordinates remain 640x360, but all framebuffer
// and static-background rendering runs at the canvas/device native pixel resolution.
// External authority: relay_moth_maps.json, relay_moth_story.json,
// relay_moth_sprites.json, relay_moth_pixel_luts.json.

const W=640, H=360, TILE=16, FLOOR_TILE=4, GRID_W=40, GRID_H=19, PLAY_H=304, BOTTOM_H=56;
const PLAYER_COLLISION_R=2.40, WALL_COLLISION_INSET=4.10;
const STARTING_MOTHS=2;
const HD_WORLD_SCALE_DEFAULT=.18, PLAYER_SPEED=72, MOUSE_MAX_SPEED=58;
const BLOCKER_FOREGROUND_FRACTION=.52;
const TAU=Math.PI*2;
const $=s=>document.querySelector(s);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lerp=(a,b,t)=>a+(b-a)*t;
const dist=(a,b,c,d)=>Math.hypot(a-c,b-d);
const sign=v=>v>0?1:v<0?-1:0;
function hash32(a,b=0,c=0){let x=(a*374761393+b*668265263+c*2246822519)>>>0;x=(x^(x>>>13))*1274126177>>>0;return (x^(x>>>16))>>>0}
function h01(a,b=0,c=0){return hash32(a,b,c)/4294967295}
function hexRgb(s){s=(s||'#000000').replace('#','');return [parseInt(s.slice(0,2),16)/255,parseInt(s.slice(2,4),16)/255,parseInt(s.slice(4,6),16)/255]}
function rgbHex(r,g,b){return '#'+[r,g,b].map(v=>clamp(Math.round(v),0,255).toString(16).padStart(2,'0')).join('').toUpperCase()}
function download(name,text,type='application/json'){const b=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function downloadBlob(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
async function loadJSON(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`${url}: HTTP ${r.status}`);return r.json()}
function deepClone(x){return JSON.parse(JSON.stringify(x))}
const MAX_FRAMEBUFFER_PIXELS=8294400; // 3840x2160: prevents pathological browser zoom/DPR backing stores.
function releaseCanvasBacking(c){if(!c)return;try{c.width=1;c.height=1}catch(_e){}}

