  walkablePixel(x,y,r=PLAYER_COLLISION_R){return this.circleClear(x,y,r)}
  resolveCircle(x,y,r=PLAYER_COLLISION_R){
    const eps=.015,minX=TILE+r+eps,maxX=W-TILE-r-eps,minY=TILE+r+eps,maxY=PLAY_H-TILE-r-eps; x=clamp(x,minX,maxX);y=clamp(y,minY,maxY);
    for(let pass=0;pass<5;pass++){
      let changed=false;const tx0=Math.max(0,Math.floor((x-r)/TILE)-1),tx1=Math.min(GRID_W-1,Math.floor((x+r)/TILE)+1),ty0=Math.max(0,Math.floor((y-r)/TILE)-1),ty1=Math.min(GRID_H-1,Math.floor((y+r)/TILE)+1);
      for(let ty=ty0;ty<=ty1;ty++)for(let tx=tx0;tx<=tx1;tx++){
        const rect=this.collisionRect(tx,ty);if(!rect)continue;const [l,t,rt,b]=rect,qx=clamp(x,l,rt),qy=clamp(y,t,b);let cx=x-qx,cy=y-qy,d2=cx*cx+cy*cy;if(d2>=r*r-1e-8)continue;
        if(d2>1e-10){const d=Math.sqrt(d2),push=r-d+eps;x+=cx/d*push;y+=cy/d*push}
        else{const dl=Math.abs(x-l),dr=Math.abs(rt-x),dtp=Math.abs(y-t),db=Math.abs(b-y),m=Math.min(dl,dr,dtp,db);if(m===dl)x=l-r-eps;else if(m===dr)x=rt+r+eps;else if(m===dtp)y=t-r-eps;else y=b+r+eps}
        x=clamp(x,minX,maxX);y=clamp(y,minY,maxY);changed=true
      }
      if(!changed)break
    }
    return[x,y]
  }
  move(x,y,dx,dy,r=PLAYER_COLLISION_R){
    const stepMax=1.1,steps=Math.max(1,Math.ceil(Math.max(Math.abs(dx),Math.abs(dy))/stepMax)),sx=dx/steps,sy=dy/steps;let px=x,py=y;
    for(let i=0;i<steps;i++) [px,py]=this.resolveCircle(px+sx,py+sy,r);
    return[px,py]
  }
  movePlayer(x,y,dx,dy,r=PLAYER_COLLISION_R){
    // v3.98: direct deterministic swept-slide controller retained.
    // No depenetration, candidate scoring, tangent teleports, or correction snaps.
    // A true diagonal is attempted first; on contact, the same substep slides on
    // individual axes in a stable order. Every result comes only from current
    // position + requested input, so keyboard motion cannot jump sideways.
    const mag=Math.hypot(dx,dy);if(mag<1e-7)return[x,y];
    const stepMax=.42,steps=Math.max(1,Math.ceil(Math.max(Math.abs(dx),Math.abs(dy))/stepMax)),sx=dx/steps,sy=dy/steps;
    let px=x,py=y;const xFirst=Math.abs(dx)>=Math.abs(dy);
    for(let i=0;i<steps;i++){
      const nx=px+sx,ny=py+sy;
      if(this.circleClear(nx,ny,r)){px=nx;py=ny;continue}
      if(xFirst){
        if(Math.abs(sx)>1e-9&&this.circleClear(px+sx,py,r))px+=sx;
        if(Math.abs(sy)>1e-9&&this.circleClear(px,py+sy,r))py+=sy;
      }else{
        if(Math.abs(sy)>1e-9&&this.circleClear(px,py+sy,r))py+=sy;
        if(Math.abs(sx)>1e-9&&this.circleClear(px+sx,py,r))px+=sx;
      }
    }
    return[px,py]
  }
  nearestWalkable(t){if(this.walkable(t))return t;const q=[t],seen=new Set([t.join(',')]);while(q.length){const p=q.shift();for(const n of [[p[0]+1,p[1]],[p[0]-1,p[1]],[p[0],p[1]+1],[p[0],p[1]-1]]){const k=n.join(',');if(seen.has(k)||n[0]<1||n[0]>=GRID_W-1||n[1]<1||n[1]>=GRID_H-1)continue;if(this.walkable(n))return n;seen.add(k);q.push(n)}}return[2,2]}
  findPath(start,target){start=this.nearestWalkable(start);target=this.nearestWalkable(target);const q=[start],prev=new Map([[start.join(','),null]]);let qi=0;while(qi<q.length){const p=q[qi++],pk=p.join(',');if(pk===target.join(','))break;for(const n of [[p[0]+1,p[1]],[p[0]-1,p[1]],[p[0],p[1]+1],[p[0],p[1]-1]]){const nk=n.join(',');if(prev.has(nk)||!this.walkable(n))continue;prev.set(nk,pk);q.push(n)}}const end=target.join(',');if(!prev.has(end))return[];const out=[];let k=end;while(k){const [x,y]=k.split(',').map(Number);out.push([x,y]);k=prev.get(k)}return out.reverse()}
