// Low-cost steering helpers for decorative life. They consume Room authority but never mutate it.
function roomCellKey(room,x,y){const t=room.tile(x,y);return `${t[0]},${t[1]}`}
function waterAt(room,x,y){const k=roomCellKey(room,x,y);return !!(room.water?.has(k)&&!room.bridgeOpen(k))}
function safeActorPoint(room,x,y,seed=0){
  x=clamp(x,TILE+5,W-TILE-5);y=clamp(y,TILE+5,PLAY_H-TILE-5);
  const t=room.tile(x,y);if(room.walkable(t)&&!room.water.has(`${t[0]},${t[1]}`))return room.center(t);
  const q=room.nearestWalkable(t);return room.center(q)
}
