  let ax=0,ay=0;const t=room.tile(x,y),cells=Math.max(1,Math.ceil(radius/TILE));
  for(let oy=-cells;oy<=cells;oy++)for(let ox=-cells;ox<=cells;ox++){
    const tx=t[0]+ox,ty=t[1]+oy;if(tx<0||ty<0||tx>=GRID_W||ty>=GRID_H)continue;const k=`${tx},${ty}`,wet=room.water.has(k)&&!room.bridgeOpen(k),blocked=room.border.has(k)||room.walls.has(k)||wet;if(!blocked)continue;
    const cx=tx*TILE+TILE/2,cy=ty*TILE+TILE/2,dx=x-cx,dy=y-cy,d=Math.hypot(dx,dy)||.001;if(d>radius+TILE*.72)continue;const q=clamp(1-d/(radius+TILE*.72),0,1),w=wet?waterWeight:1;ax+=dx/d*q*q*w;ay+=dy/d*q*q*w;
  }
