  _dead(v,d=.20){v=Number(v)||0;const a=Math.abs(v);return a<=d?0:Math.sign(v)*(a-d)/(1-d)}
  _axis(p,i){const raw=Number(p.axes?.[i])||0,base=p.mapping==='standard'?0:(this.axisBaseline[i]||0);return this._dead(clamp(raw-base,-1,1))}
  _value(p,i){return clamp(Number(p.buttons?.[i]?.value??(p.buttons?.[i]?.pressed?1:0))||0,0,1)}
  _pov(v){if(!Number.isFinite(v))return[0,0];const values=[[-1,0,-1],[-.714,1,-1],[-.428,1,0],[-.143,1,1],[.143,0,1],[.429,-1,1],[.714,-1,0],[1,-1,-1]];let best=null,bd=.13;for(const [q,x,y] of values){const d=Math.abs(v-q);if(d<bd){best=[x,y];bd=d}}return best||[0,0]}
