    const p=this._pad();if(!p)return{connected:false,x:0,y:0,gather:false,just:new Set(),held:new Set(),id:''};const identity=`${p.index}|${p.id}|${p.buttons?.length||0}|${p.axes?.length||0}`;if(identity!==this.padIdentity)this._seed(p,now);
    let x=0,y=0;const pairs=[[0,1],[2,3],[3,4]],first=[this._axis(p,0),this._axis(p,1)];let best=first,bm=Math.hypot(...best);if(p.mapping!=='standard'){for(const [a,b] of pairs){if(a>=p.axes.length||b>=p.axes.length)continue;const q=[this._axis(p,a),this._axis(p,b)],m=Math.hypot(...q);if(m>bm+.12&&m<=1.35){best=q;bm=m}}}x=best[0];y=best[1];
