    if(held.has(14))x-=1;if(held.has(15))x+=1;if(held.has(12))y-=1;if(held.has(13))y+=1;if(p.mapping!=='standard'&&p.axes.length>4&&Math.abs(x)+Math.abs(y)<.05){const hi=p.axes.length-1,raw=Number(p.axes[hi])||0,base=this.axisBaseline[hi]||0;if(Math.abs(raw-base)>.12){const [px,py]=this._pov(raw);x+=px;y+=py}}
