  resumeFromInput(){if(this.paused){this.paused=false;const b=$('#pauseBadge');if(b)b.classList.add('hidden');this.toast('PLAY',.8)}}
  sparkPulse(source='manual'){const now=performance.now(),gap=source==='gamepad'?320:180;if(now-this.lastManualPulse<gap)return false;this.lastManualPulse=now;this.pulseSource=source;this.particles.pulse(this.x,this.y);this.fx.add('pulse',this.x,this.y,null,.82,[1.15,0,0,0]);this.renderer.surfaceFX?.addWaterRipple(this.x,this.y,{radius:92,amplitude:.92,foam:.55,life:1.25});this.flock.pulse=1;this.pulseLight=1;return true}
