    for(const obj of done){const line=document.createElement('div');line.className='objectiveDone';line.textContent=`✓ ${this.completionText(obj)}`;if(this.completionHud===this.completionText(obj)&&this.completionHudTimer>0)line.classList.add('latest');hud.append(line)}
