  checkMothPickups(){for(const m of this.room.mothPickups){if(this.state.hasMoth(m.id))continue;const [mx,my]=this.room.center(m.tile);if(dist(this.x,this.y,mx,my)<17){this.state.collectMoth(m.id);this.flock.addMoth(m,this.x,this.y);const color=this.luts.rgb('moth_spark',m.colour_index??220);this.particles.burst('pickup',mx,my,34);this.fx.add('pickup',mx,my,color,1.15);this.completionHud='A relay moth joined your sparkling flock.';this.completionHudTimer=3.5;this.updateUI();this.toast(`Relay moth collected · ${this.flock.m.length}/${this.totalMoths}`,1.6);break}}}
