function toggleMixer(){if(!game)return;const e=$('#lutMixer');e.classList.toggle('hidden');buildMixer();}
function buildMixer(){if(!game)return;const box=$('#channelRows');box.innerHTML='';for(const ch of game.luts.channels()){const row=document.createElement('div');row.className='channelRow';row.dataset.channel=ch;const n=document.createElement('div');n.className='channelName';n.textContent=ch;const b=document.createElement('div');b.className='bankName';b.textContent=displayTheme(game.luts.themeForChannel(ch));const prev=document.createElement('button');prev.className='miniBtn';prev.textContent='◀';const next=document.createElement('button');next.className='miniBtn';next.textContent='▶';prev.onclick=()=>{game.luts.cycleTheme(ch,-1);game.bgKey='';game.ensureBackground(true);buildMixer()};next.onclick=()=>{game.luts.cycleTheme(ch,1);game.bgKey='';game.ensureBackground(true);buildMixer()};row.append(n,b,prev,next);box.append(row)}}
function displayTheme(t){return({'Moonlit Copper':'DREAM','Mint Circuit':'FOREST','Berry Starlight':'BERRY','Sunrise Tin':'SUNSET','Winter Relay':'WINTER'})[t]||t.toUpperCase()}
function toggleHelp(){$('#helpModal').classList.toggle('hidden')}
function toggleColourLab(){$('#colourLab').classList.toggle('hidden');refreshColourLab()}
function toggleAdvanced(){$('#advancedLut').classList.toggle('hidden');refreshAdvanced()}
function toggleGraphics(){$('#graphicsMenu').classList.toggle('hidden');syncGraphicsMenu()}
function toggleLevelMenu(){const e=$('#levelMenu');e.classList.toggle('hidden');buildLevelMenu();if(!e.classList.contains('hidden'))setTimeout(()=>document.querySelector('#levelList .levelEntry:not(:disabled)')?.focus(),0)}

function refreshColourLab(){if(!game)return;const tabs=$('#paletteTabs');tabs.innerHTML='';game.luts.themes().forEach((t,i)=>{const b=document.createElement('button');b.textContent=`${i+1} ${displayTheme(t)}`;b.className=i===colourLabTheme?'active':'';b.onclick=()=>{colourLabTheme=i;refreshColourLab()};tabs.append(b)});const p=$('#labPreview');p.innerHTML='';const theme=game.luts.themes()[colourLabTheme],l=game.luts.data.themes[theme].luts.moth_wings;for(let i=0;i<256;i+=8){const d=document.createElement('div');d.style.background=l[i];p.append(d)}}
let colourLabTheme=0;
const NAME_COLORS={PINK:'#FF69CE',PURPLE:'#833EFF',BLUE:'#387BFF',SKY:'#5FE6FF',TEAL:'#18B9B0',MINT:'#78F7C1',GREEN:'#57C96B',YELLOW:'#FFE66E',ORANGE:'#FF9B55',RED:'#FF5C67',WHITE:'#FFF9F4',BLACK:'#080712'};
function parseColourText(s){s=s.trim().toUpperCase();if(NAME_COLORS[s])return NAME_COLORS[s];if(/^#[0-9A-F]{6}$/.test(s))return s;return null}
function mixHex(a,b,t){const A=hexRgb(a).map(v=>v*255),B=hexRgb(b).map(v=>v*255);return rgbHex(lerp(A[0],B[0],t),lerp(A[1],B[1],t),lerp(A[2],B[2],t))}
function generateChildPalette(mode='normal'){if(!game)return;let a=parseColourText($('#colourA').value)||'#FF69CE',b=parseColourText($('#colourB').value);if(!b){const A=hexRgb(a).map(v=>v*255);b=rgbHex(255-A[0]*.5,255-A[1]*.5,255-A[2]*.5)}const theme=game.luts.themes()[colourLabTheme];game.luts.pushUndo();const luts=game.luts.data.themes[theme].luts;for(const [name,lut] of Object.entries(luts)){const seed=hash32(name.length,colourLabTheme,mode.length),reverse=(mode==='order'&&seed&1);for(let i=0;i<256;i++){let t=i/255;if(mode==='pattern')t=(Math.sin(t*TAU*(2+seed%5)+seed)+1)/2;if(mode==='colour'){const r=h01(seed,i,5)*.22-.11;t=clamp(t+r,0,1)}if(reverse)t=1-t;let c=mixHex(a,b,t);const rgb=hexRgb(c).map(v=>v*255);const dark=name==='sky'||name==='tree_shadow'||name==='ui'||name==='blockers'?0.42:0.72;const br=lerp(dark,1,Math.pow(i/255,.55));lut[i]=rgbHex(rgb[0]*br,rgb[1]*br,rgb[2]*br)}}game.bgKey='';game.ensureBackground(true);refreshColourLab();buildMixer();game.toast('Palette generated',1.5)}

function refreshAdvanced(){if(!game)return;const ts=$('#advancedTheme'),es=$('#advancedElement');if(!ts.options.length){for(const t of game.luts.themes())ts.add(new Option(displayTheme(t),t));for(const e of Object.keys(game.luts.data.themes[game.luts.themes()[0]].luts))es.add(new Option(e.toUpperCase(),e));ts.onchange=refreshAdvanced;es.onchange=drawLutGrid}drawLutGrid()}
function drawLutGrid(){if(!game)return;const theme=$('#advancedTheme').value||game.luts.themes()[0],element=$('#advancedElement').value||'sky',lut=game.luts.data.themes[theme].luts[element];const c=$('#lutGrid'),ctx=c.getContext('2d');for(let i=0;i<256;i++){ctx.fillStyle=lut[i];ctx.fillRect((i%32)*16,Math.floor(i/32)*32,16,32)}}
function setAdvancedCell(i){$('#advancedIndex').value=i;const theme=$('#advancedTheme').value,element=$('#advancedElement').value;$('#advancedColour').value=game.luts.data.themes[theme].luts[element][i]}

async function reloadLuts(){try{const d=await loadJSON('relay_moth_pixel_luts.json?'+Date.now());game.luts=new LUTManager(d);game.painter.luts=game.luts;game.bgKey='';game.ensureBackground(true);refreshEditors();game.toast('LUT file reloaded',1.5)}catch(e){game.toast('LUT reload rejected: '+e.message,3)}}
function refreshEditors(){buildMixer();refreshColourLab();refreshAdvanced()}
function exportRaster(){if(!game)return;const c=game.painter.build(game.room,game.state,W,H);c.convertToBlob({type:'image/png'}).then(b=>{downloadBlob(`${game.room.key}-pretty39952-static.png`,b);releaseCanvasBacking(c)}).catch(e=>{releaseCanvasBacking(c);game.toast('Raster export failed: '+e.message,3)});const semantic={schema:'relay-moth-raster/v3.9952',resolution:[W,H],room:game.room.key,completed:game.room.spec.objects.filter(o=>game.state.isDone(o.object_id)).map(o=>o.object_id),channels:Object.fromEntries(game.luts.channels().map(c=>[c,game.luts.themeForChannel(c)])),live_layer:['spark_cursor','relay_moths','followers','foreground_scenery','uncompleted_objectives','completion_particles','UI/dialogue']};download(`${game.room.key}-pretty39952-static.json`,JSON.stringify(semantic,null,2)+'\n')}

function buildLevelMenu(){if(!game)return;const box=$('#levelList');box.innerHTML='';game.storyData.rooms.forEach((r,i)=>{const b=document.createElement('button'),done=game.state.roomComplete(r),unlocked=game.roomUnlocked(i),moths=(game.maps.rooms[r.key].moth_pickups||[]).filter(m=>game.state.hasMoth(m.id)).length,total=(game.maps.rooms[r.key].moth_pickups||[]).length;b.className=unlocked?'levelEntry':'levelEntry locked';b.disabled=!unlocked;b.innerHTML=`<b>${i+1}. ${r.title}</b><span>${done?'OBJECTIVES ✓':'OBJECTIVES ···'} · MOTHS ${moths}/${total}</span>`;b.onclick=()=>game.gotoRoom(i);box.append(b)});$('#saveSummary').textContent=`OBJECTIVES ${game.state.completed.size} · RELAY MOTHS ${game.flock.m.length}/${game.totalMoths}`}


function syncGraphicsMenu(){if(!game)return;for(const el of document.querySelectorAll('[data-gfx]')){const k=el.dataset.gfx;if(el.type==='checkbox')el.checked=!!game.graphics[k];else el.value=game.graphics[k];const out=document.querySelector(`[data-gfx-out="${k}"]`);if(out)out.textContent=typeof game.graphics[k]==='number'?Number(game.graphics[k]).toFixed(k==='grain'?3:2):(game.graphics[k]?'ON':'OFF')}}
function setupGraphicsMenu(){const syncSurface=(rebuildFoliage=false)=>{game.renderer.surfaceFX?.water?.setQuality(game.graphics.waterQuality??2);game.renderer.surfaceFX?.grass?.rebuild(game.graphics);if(rebuildFoliage)game.renderer.foliageFX?.rebuild(game.graphics)};for(const el of document.querySelectorAll('[data-gfx]')){const apply=()=>{const k=el.dataset.gfx;if(el.type==='checkbox')game.graphics[k]=el.checked;else{let v=Number(el.value);if(!Number.isFinite(v))return;if(el.min!=='')v=Math.max(Number(el.min),v);if(el.max!=='')v=Math.min(Number(el.max),v);game.graphics[k]=v}game.flock?.configure(game.graphics);syncSurface(k==='foliageQuality');saveGraphicsSettings(game.graphics);syncGraphicsMenu()};el.addEventListener('change',apply);el.addEventListener('blur',apply)}$('#resetGraphics').onclick=()=>{game.graphics={...GRAPHICS_DEFAULTS};game.ambientLevel=Number(game.graphics.ambientInitial);game.flock?.configure(game.graphics);syncSurface(true);saveGraphicsSettings(game.graphics);syncGraphicsMenu();game.toast('Graphics defaults restored',1.4)};syncGraphicsMenu()}

function setupEditors(){document.addEventListener('keydown',e=>{if(e.key==='Escape'){for(const id of ['lutMixer','graphicsMenu','colourLab','advancedLut','helpModal','levelMenu'])$('#'+id).classList.add('hidden')}if(!$('#lutMixer').classList.contains('hidden')){const chs=game.luts.channels();let active=document.querySelector('.channelRow.active'),idx=active?chs.indexOf(active.dataset.channel):0;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();idx=(idx+(e.key==='ArrowDown'?1:-1)+chs.length)%chs.length;document.querySelectorAll('.channelRow').forEach(x=>x.classList.toggle('active',x.dataset.channel===chs[idx]))}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();game.luts.cycleTheme(chs[idx],e.key==='ArrowRight'?1:-1);game.bgKey='';game.ensureBackground(true);buildMixer();setTimeout(()=>document.querySelector(`[data-channel="${chs[idx]}"]`)?.classList.add('active'),0)}}if(!$('#colourLab').classList.contains('hidden')&&/^[1-5]$/.test(e.key)){colourLabTheme=Number(e.key)-1;refreshColourLab()}});
  $('#generatePalette').onclick=()=>generateChildPalette('normal');$('#orderRandom').onclick=()=>generateChildPalette('order');$('#colourRandom').onclick=()=>generateChildPalette('colour');$('#patternRandom').onclick=()=>generateChildPalette('pattern');$('#colourA').addEventListener('keydown',e=>{if(e.key==='Enter')generateChildPalette('normal')});$('#colourB').addEventListener('keydown',e=>{if(e.key==='Enter')generateChildPalette('normal')});
  $('#lutGrid').onclick=e=>{const r=e.target.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*512,y=(e.clientY-r.top)/r.height*256,i=Math.floor(x/16)+Math.floor(y/32)*32;setAdvancedCell(clamp(i,0,255))};$('#advancedIndex').oninput=e=>setAdvancedCell(Number(e.target.value));$('#applyAdvanced').onclick=()=>{const theme=$('#advancedTheme').value,element=$('#advancedElement').value,i=Number($('#advancedIndex').value),c=parseColourText($('#advancedColour').value);if(!c)return;game.luts.pushUndo();game.luts.data.themes[theme].luts[element][i]=c;game.bgKey='';game.ensureBackground(true);drawLutGrid()};
  $('#resetObjectives').onclick=()=>game.resetCurrentRoom();$('#resetSave').onclick=()=>game.resetAllProgress();
}

async function loadImage(url){return new Promise((resolve,reject)=>{const img=new Image();img.crossOrigin='anonymous';img.onload=()=>resolve(img);img.onerror=reject;img.src=url})}
async function main(){try{const [maps,story,sprites,luts,hdAtlas,effects]=await Promise.all([loadJSON('relay_moth_maps.json'),loadJSON('relay_moth_story.json'),loadJSON('relay_moth_sprites.json'),loadJSON('relay_moth_pixel_luts.json'),loadJSON('hd_remake_atlas.json'),loadJSON('relay_moth_effects.json')]);const [ref,spec,normal]=await Promise.all([loadImage(hdAtlas.image),loadImage(hdAtlas.specular_image),loadImage(hdAtlas.normal_image)]);DATA={maps,story,sprites,luts,hdAtlas,effects};game=new Game($('#game'),DATA,ref,null,spec,normal);setupEditors();setupGraphicsMenu();buildMixer();refreshColourLab();refreshAdvanced();setupWysiwygEditor(game);window.game=game;document.body.dataset.ready='1'}catch(e){console.error(e);document.body.innerHTML=`<pre style="color:#fff;padding:30px">Relay Moth Forest could not start.

${e.stack||e}

Reload this hosted page or open the source repository so JSON/assets are served over localhost.</pre>`}}
main();
